                let has_bare_pool = owner_method.as_ref().is_some_and(|(owner, method)| {
                    self.methods.contains_key(&(owner.clone(), method.clone()))
                });

                if has_bare_pool
                    && name.contains("::")
                    && self.rust_graph_qualified_target_is_free_fn(graph, site, file, from)
