7	fn graph(src: &str) -> CallGraph {
8	    let files = BTreeMap::from([(
9	        "svc.ts".to_string(),
10	        ParsedFile::parse("svc.ts", src, Language::TypeScript).expect("parse ts"),
11	    )]);
12	    CallGraph::build(&files)
13	}
