15	fn graph_files(srcs: &[(&str, &str)]) -> CallGraph {
16	    let files: BTreeMap<_, _> = srcs
17	        .iter()
18	        .map(|(path, src)| {
19	            (
20	                (*path).to_string(),
21	                ParsedFile::parse(path, src, Language::TypeScript).expect("parse ts"),
22	            )
23	        })
24	        .collect();
25	    CallGraph::build(&files)
26	}
