28	fn site(cg: &CallGraph, caller: &str, callee: &str) -> CallSite {
29	    cg.calls
30	        .iter()
31	        .find(|(fid, _)| fid.name == caller)
32	        .and_then(|(_, sites)| sites.iter().find(|s| s.callee_name == callee))
33	        .unwrap_or_else(|| panic!("missing {caller}->{callee}"))
34	        .clone()
35	}
